{For any complete non-compact Riemannian manifold $(M^3, g)$ with $Rc\geq 0$ and $R\geq 2$, 
\begin{enumerate}
\item[(1)].  if $(M^3, g)$ has only one end,  then $\displaystyle 0< \mathrm{V}_{M^3, 1}\leq 2\pi$,
\item[(2)]. if $(M^3,g)$ has at least two ends, then $(M^3,g)$ is isometric to a cylinder $S\times\mathbb{R}$ with $S$ being a closed surface of sectional curvature at least one, and $\displaystyle 0< \mathrm{V}_{M^3, 1}\leq 4\pi$. 
\item[(3)].  moreover $\mathrm{V}_{M^3, 1}= 4\pi$ if and only if $(M^3,g)$ is isometric to a cylinder $\mathbb{S}^2\times\mathbb{R}$. 
\end{enumerate}
}

{For any complete non-compact Riemannian manifold $(M^3, g)$ with $Rc\geq 0$ and $R\geq 2$, 
\begin{enumerate}
\item[(1)].  if $(M^3, g)$ has only one end,  then $\displaystyle 0< \mathrm{V}_{M^3, 1}\leq 2\pi$,
\item[(2)]. if $(M^3,g)$ has at least two ends, then $(M^3,g)$ is isometric to a cylinder $S\times\mathbb{R}$ with $S$ being a closed surface of sectional curvature at least one, and $\displaystyle 0< \mathrm{V}_{M^3, 1}\leq 4\pi$. 
\item[(3)].  moreover $\mathrm{V}_{M^3, 1}= 4\pi$ if and only if $(M^3,g)$ is isometric to the cylinder $\mathbb{S}^2\times\mathbb{R}$,  where $\mathbb{S}^2$ is the unit round sphere in $\mathbb{R}^3$.
\end{enumerate}
}

{Assume $(M^3, g)$ is a complete non-compact Riemannian manifold with $R\geq 2$ and only one end, also it is simply connected and $p\in M^3$.  For any $\varepsilon>0$ and $L> \sqrt{2}\pi(1+\varepsilon)$, there is $k_0= k_0(\varepsilon, L)\in \mathbb{Z}^+$; such that for any $k\geq k_0$, one can find a smooth compact surface $\Sigma_k\subseteq E_k- \overline{E_{k+ 1}}$, which satisfies
\begin{enumerate}
\item[(1)]. $\Sigma_k$ separates $\partial E_k$ from $\partial E_{k+ 1}$;
\item[(2)]. $\displaystyle V(\Sigma_k)\leq \frac{4\pi}{1- \frac{2\pi^2(1+\varepsilon)^2}{L^2}}$. 
\item[(3)]. $\mathrm{Diam}(\Sigma_k)\leq \frac{2\pi}{\sqrt{3(1- \frac{2\pi^2(1+ \varepsilon)^2}{L^2})}}$.
\end{enumerate}
}

{Assume $(M^3, g)$ has only one end with $Rc\geq 0$ and $R\geq 2$. We also assume it is simply connected.  For any $p\in M^3$ and a unit speed geodesic ray $\gamma$ starting from $p$,  any $ \varepsilon\in (0,  1),  \delta\in (0,\frac{1}{100})$ and $L> 8\pi$,  there is $k_0= k_0(\delta, \varepsilon, L)\in \mathbb{Z}^+$ such that 
\begin{align}
\sup_{x, y\in \big(\partial B_p(r)\cap B_{\gamma(k\cdot L)}(5L)\big)}d_g(x, y)\leq \frac{4\pi}{\sqrt{3(1- \frac{2\pi^2(1+ \varepsilon)^2}{L^2})}}+ 9\delta\cdot L, \quad \quad \quad \forall k\geq k_0, r> 0.  
\end{align}
}

{Assume $(M^3, g)$ has only one end and $Rc\geq 0, R\geq 2$, furthermore assume it is simply connected.  For any $\varepsilon\in (0, 1), \delta\in (0, \frac{1}{100}), L> 8\pi$, there is $k_0= k_0(\varepsilon, \delta, L)\in \mathbb{Z}^+$; such that (see Figure fig:lem annulus is not too far from p)
\begin{align}
N_k\subseteq \Big[B_p((k+ 1)L+ 2c+ 10\delta\cdot L)- \overline{B_p(kL)}\Big],  \quad \quad \quad \forall k\geq k_0,   
\end{align}
where $\displaystyle c= \frac{2\pi}{\sqrt{3(1- \frac{2\pi^2(1+ \varepsilon)^2}{L^2})}}$. 
}

Let $X, Y$ be two positive semi-definite $(n\times n)$-matrices, then
    \begin{align*}
        \det(X+Y)\geq \det(X)+\det(Y).
    \end{align*}

If $(M^n, g)$ is a complete Riemannian manifold and $r: \Omega\rightarrow \mathbb{R}^+$ is a smooth function, where $\Omega\subseteq \mathbb{S}_pM$ is an open set. Let $\varphi(\theta)=\exp_p(r(\theta)\theta)$; then
    \begin{align}
        J_\varphi(\theta)\geq J(r(\theta),\theta), \quad \quad \quad \forall \theta\in \Omega;  
    \end{align}
where $J_\varphi(\theta)$ is the Jacobian determinant of $\varphi$.

If $(M^n, g)$ has $Rc\geq 0$ and only one end,   suppose $\Sigma \subset  N_{k- 1}$ is a smooth, compact hypersurface separating $\partial E_{k- 1}$ from $\partial E_{k}$, then
\begin{align}
V\Big((\partial B_p(s)\cap N_k)- \mathrm{Cut}(p)\Big)\leq (\frac{s}{(k- 1)L})^{n- 1}\cdot V(\Sigma), \quad \quad \forall s> kL.  
\end{align}

{If $\Sigma$ is a $\mu$-bubble hypersurface with respect to $(h, u, \mathcal{C})$ in $(N, \partial_{-}N, \partial_{+}N)$,  where $N$ is $n$-dim Riemannian manifold with $n\geq 3$; then for any $\psi\in C^\infty(\Sigma)$,  we have
\begin{align}
&\int_\Sigma |\nabla_\Sigma \psi|^2 u- \frac{1}{2}(R_N- R_\Sigma+ |\mathring{A}_\Sigma|^2)\cdot \psi^2 u+ (\Delta_N u- \Delta_\Sigma u)\psi^2  \\
&-\frac{1}{2}u^{-1}\langle \nabla_N u, \vec{n}\rangle^2\psi^2- \frac{1}{2}\{h^2+ 2\langle \nabla_N h, \vec{n}\rangle\}\psi^2 u \geq 0;
\end{align}
where $\mathring{A}_\Sigma$ is the traceless part of second fundamental form of $\Sigma\subseteq N$,  $\vec{n}$ is the unit normal vector of $\Sigma\subseteq N$,  and $R_N, R_\Sigma$ are the intrinsic scalar curvature of $N$ and $\Sigma$ respectively.
}

{For compact $(\Sigma^2, g)$, if there is a smooth function $u> 0$ such that 
\begin{align}
-\Delta u\geq (K- K_\Sigma)u,  
\end{align}
for some constant $K> 0$, then $\mathrm{Diam}(\Sigma)\leq \frac{2\pi}{\sqrt{3K}}$. 
}

For any closed subset $K\subsetneq (M^3,g)$, there is $f\in C^\infty(M^3)$ such that 
    \begin{align*}
        f|_{K}=0,\quad f|_{K^c}>0.
    \end{align*}

{For any $p\in (M^3, g)$ and $k\in \mathbb{Z}^+, L> 0$, there is $f\in C^\infty(M^3)$ with 
\begin{align}
f\big|_{\partial E_k}\leq kL, \quad f\big|_{\partial E_{k+ 1}}> (k+ \frac{1}{2})L, \quad  \text{and} \ (k+ \frac{1}{2})L\ \text{is a regular value of} \ f.  
\end{align}
}

For any $\varepsilon>0$, there is a continuous function $\rho_k(x):\overline{N_k}\to [-L/2,L/2]$,  where $N_k= E_k- \overline{E_{k+ 1}}$, such that $\rho_k$ is smooth on $N_k$, $\rho_k(N_k)\subset(-L/2,L/2)$ and
\begin{align*}
    \rho_k|_{\partial E_k} = -L/2, \quad \rho_k|_{\partial E_{k+1}} = L/2, \quad |\nabla_M \rho_k|<(1+\varepsilon)^2.
\end{align*}
